"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

_INCLUDE = "@include"


def _include_target(raw):
    parts = raw.split(None, 1)
    if not parts or parts[0] != _INCLUDE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("{}: missing path".format(_INCLUDE))
    return parts[1].strip()


def _read(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(lines, base_dir, stack):
    out = []
    for raw in lines:
        target = _include_target(raw)
        if target is None:
            out.append(raw)
            continue
        inc_path = os.path.abspath(os.path.join(base_dir, target))
        key = os.path.realpath(inc_path)
        if key in stack:
            raise ConfigError("include cycle detected: {}".format(inc_path))
        if not os.path.isfile(inc_path):
            raise ConfigError("included file not found: {}".format(inc_path))
        try:
            inc_lines = _read(inc_path)
        except (OSError, UnicodeDecodeError) as exc:
            raise ConfigError("cannot read included file {}: {}".format(inc_path, exc))
        out.extend(_expand(inc_lines, os.path.dirname(inc_path), stack + (key,)))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read(path)
    abs_path = os.path.abspath(path)
    lines = _expand(lines, os.path.dirname(abs_path), (os.path.realpath(abs_path),))
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
