import tempfile, os
from miniconf.loader import load
from miniconf.errors import ConfigError
with tempfile.TemporaryDirectory() as d:
    os.mkdir(os.path.join(d,'sub'))
    w=lambda n,t: open(os.path.join(d,n),'w').write(t)
    w('a.conf','a=1\n@include b.conf\n'); w('b.conf','@include a.conf\n')
    try: load(os.path.join(d,'a.conf'))
    except ConfigError as e: print('cycle ok', e)
    w('m.conf','@include nope.conf\n')
    try: load(os.path.join(d,'m.conf'))
    except ConfigError as e: print('missing ok')
    w('sub/in.conf','x=inc\ny=inc\n'); w('o.conf','x=before\n@include sub/in.conf\ny=after\n')
    c=load(os.path.join(d,'o.conf')); print(c.get('x'),c.get('y'))
EOF
